<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ChevronDown, ChevronRight, GripVertical, Pencil, Plus, Power, Trash2 } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import type { Category, LedgerType } from '@/domain/models/category'
import { useAppStore } from '@/stores/app-store'
import AppDialog from '@/components/AppDialog.vue'
import CategoryIcon from '@/components/CategoryIcon.vue'
import { colorOf, softOf } from '@/domain/services/category-color'

const store = useAppStore()
const route = useRoute()
const router = useRouter()
const type = ref<LedgerType>(route.query.type === 'income' ? 'income' : 'expense')
const expanded = ref(new Set<string>())
const deleting = ref<Category>()
const migrationTarget = ref('')
const busy = ref(false)
const sorting = ref(false)
const dragVisual = ref<{ id: string; targetId: string | null; before: boolean } | null>(null)
interface DragGesture {
  id: string
  parentId: string | null
  pointerId: number
  startX: number
  startY: number
  handle: HTMLElement
  active: boolean
  timer?: number
}
let dragGesture: DragGesture | undefined

const groups = computed(() => store.categories
  .filter((category) => category.type === type.value && category.parentId === null)
  .sort((a, b) => a.sortOrder - b.sortOrder || a.id.localeCompare(b.id))
  .map((parent) => {
    const children = store.categories.filter((category) => category.parentId === parent.id).sort((a, b) => a.sortOrder - b.sortOrder || a.id.localeCompare(b.id))
    return { parent, children, activeCount: children.filter((category) => !category.disabled).length }
  }))
const deleteTransactionCount = computed(() => deleting.value ? store.transactions.filter((item) => item.categoryId === deleting.value?.id).length : 0)
const migrationOptions = computed(() => {
  const typeValue = deleting.value?.type
  const activeParents = new Set(store.categories.filter((category) => category.type === typeValue && category.parentId === null && !category.disabled).map((category) => category.id))
  return store.categories.filter((category) => category.type === typeValue && category.parentId && activeParents.has(category.parentId) && category.id !== deleting.value?.id && !category.disabled)
})

function resetExpanded(): void {
  expanded.value = new Set()
}

function stopDrag(): void {
  if (dragGesture?.timer) window.clearTimeout(dragGesture.timer)
  if (dragGesture?.handle.hasPointerCapture?.(dragGesture.pointerId)) dragGesture.handle.releasePointerCapture(dragGesture.pointerId)
  dragGesture = undefined
  dragVisual.value = null
}

onBeforeUnmount(stopDrag)

onMounted(async () => {
  await store.initialize()
  resetExpanded()
})
watch(type, (value) => {
  stopDrag()
  resetExpanded()
  router.replace({ query: { ...route.query, type: value } })
})

function requireWrite(): boolean {
  if (store.canWrite) return true
  store.notify('激活授权码后才能修改分类', 'error')
  router.push('/settings/license')
  return false
}

function toggleExpand(id: string): void {
  const next = new Set(expanded.value)
  next.has(id) ? next.delete(id) : next.add(id)
  expanded.value = next
}

function siblings(parentId: string | null): Category[] {
  if (parentId === null) return groups.value.map((group) => group.parent)
  return groups.value.find((group) => group.parent.id === parentId)?.children ?? []
}

async function saveOrder(parentId: string | null, ids: string[]): Promise<void> {
  if (sorting.value) return
  sorting.value = true
  try {
    await store.repository.reorderCategories(type.value, parentId, ids)
    await store.refresh()
    store.notify('分类顺序已保存', 'success')
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '分类排序失败', 'error')
  } finally {
    sorting.value = false
  }
}

function startDrag(category: Category, event: PointerEvent): void {
  if (sorting.value || (event.pointerType === 'mouse' && event.button !== 0) || !requireWrite()) return
  stopDrag()
  const handle = event.currentTarget as HTMLElement
  dragGesture = { id: category.id, parentId: category.parentId, pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, handle, active: false }
  handle.setPointerCapture?.(event.pointerId)
  if (event.pointerType === 'touch') {
    dragGesture.timer = window.setTimeout(() => {
      if (!dragGesture || dragGesture.pointerId !== event.pointerId) return
      dragGesture.active = true
      dragVisual.value = { id: category.id, targetId: null, before: true }
    }, 300)
  } else {
    dragGesture.active = true
    dragVisual.value = { id: category.id, targetId: null, before: true }
  }
}

function moveDrag(event: PointerEvent): void {
  const gesture = dragGesture
  if (!gesture || gesture.pointerId !== event.pointerId) return
  if (!gesture.active) {
    if (Math.abs(event.clientX - gesture.startX) > 8 || Math.abs(event.clientY - gesture.startY) > 8) stopDrag()
    return
  }
  event.preventDefault()
  const hit = document.elementFromPoint?.(event.clientX, event.clientY) as HTMLElement | null
  const row = gesture.parentId === null
    ? hit?.closest<HTMLElement>('[data-group-id]')
    : hit?.closest<HTMLElement>('[data-category-id]')
  const targetId = gesture.parentId === null ? row?.dataset.groupId : row?.dataset.categoryId
  if (!row || !targetId || targetId === gesture.id ||
      (gesture.parentId !== null && row.dataset.parentId !== gesture.parentId)) {
    dragVisual.value = { id: gesture.id, targetId: null, before: true }
    return
  }
  const bounds = row.getBoundingClientRect()
  dragVisual.value = { id: gesture.id, targetId, before: event.clientY < bounds.top + bounds.height / 2 }
}

async function finishDrag(event: PointerEvent): Promise<void> {
  const gesture = dragGesture
  if (!gesture || gesture.pointerId !== event.pointerId) return
  const visual = dragVisual.value
  stopDrag()
  if (!gesture.active || !visual?.targetId) return
  const ids = siblings(gesture.parentId).map((category) => category.id)
  const from = ids.indexOf(gesture.id)
  const target = ids.indexOf(visual.targetId)
  if (from < 0 || target < 0) return
  ids.splice(from, 1)
  const targetAfterRemoval = ids.indexOf(visual.targetId)
  ids.splice(targetAfterRemoval + (visual.before ? 0 : 1), 0, gesture.id)
  if (ids.every((id, index) => id === siblings(gesture.parentId)[index]?.id)) return
  await saveOrder(gesture.parentId, ids)
}

async function moveByKeyboard(category: Category, direction: -1 | 1, event: KeyboardEvent): Promise<void> {
  event.preventDefault()
  if (sorting.value || !requireWrite()) return
  const ids = siblings(category.parentId).map((item) => item.id)
  const index = ids.indexOf(category.id)
  const next = index + direction
  if (index < 0 || next < 0 || next >= ids.length) return
  ;[ids[index], ids[next]] = [ids[next]!, ids[index]!]
  await saveOrder(category.parentId, ids)
}

async function toggleDisabled(category: Category): Promise<void> {
  if (!requireWrite()) return
  await store.repository.putCategory({ ...category, disabled: !category.disabled, updatedAt: new Date().toISOString() })
  await store.refresh()
  store.notify(`已${category.disabled ? '启用' : '停用'}“${category.name}”`, 'success')
}

function editCategory(category: Category): void {
  if (!requireWrite()) return
  router.push(`/settings/categories/${category.id}`)
}

function iconStyle(category: Category): { background: string; color: string } {
  const color = colorOf(category, store.categories)
  return { background: softOf(color), color }
}

function closeDeleteDialog(): void {
  deleting.value = undefined
  migrationTarget.value = ''
}

function requestDelete(category: Category): void {
  if (!requireWrite()) return
  if (category.parentId === null && store.categories.some((item) => item.parentId === category.id)) {
    store.notify('请先删除或移走分组下的二级分类', 'error')
    return
  }
  deleting.value = category
  migrationTarget.value = ''
}

async function confirmDelete(): Promise<void> {
  const category = deleting.value
  if (!category) return
  busy.value = true
  try {
    if (deleteTransactionCount.value > 0) {
      if (!migrationTarget.value) throw new Error('请先选择流水迁移目标')
      const target = migrationOptions.value.find((item) => item.id === migrationTarget.value)
      if (!target) throw new Error('迁移目标不可用，请重新选择')
      const moved = await store.repository.migrateTransactionsAndDelete(category.id, target.id)
      store.notify(`已将 ${moved} 条流水迁移到“${target.name}”并删除分类`, 'success')
    } else {
      await store.repository.deleteCategory(category.id)
      store.notify(`已删除“${category.name}”`, 'success')
    }
    closeDeleteDialog()
    await store.refresh()
  } catch (cause) { store.notify(cause instanceof Error ? cause.message : '删除失败', 'error') }
  finally { busy.value = false }
}
</script>

<template>
  <main class="page categories-page">
    <div class="segmented type-tabs">
      <button type="button" :class="{ active: type === 'expense' }" @click="type = 'expense'">支出分类</button>
      <button type="button" :class="{ active: type === 'income' }" @click="type = 'income'">收入分类</button>
    </div>

    <section v-for="group in groups" :key="group.parent.id" class="category-group card" :data-group-id="group.parent.id"
      :class="{ disabled: group.parent.disabled, dragging: dragVisual?.id === group.parent.id, 'drop-before': dragVisual?.targetId === group.parent.id && dragVisual.before, 'drop-after': dragVisual?.targetId === group.parent.id && !dragVisual.before }">
      <div class="group-row">
        <button class="drag-handle" type="button" :aria-label="`拖动${group.parent.name}调整顺序`" :aria-grabbed="dragVisual?.id === group.parent.id"
          @pointerdown="startDrag(group.parent, $event)" @pointermove="moveDrag" @pointerup="finishDrag" @pointercancel="stopDrag" @contextmenu.prevent
          @keydown.up="moveByKeyboard(group.parent, -1, $event)" @keydown.down="moveByKeyboard(group.parent, 1, $event)"><GripVertical :size="19" /></button>
        <button class="expand-button" type="button" :aria-expanded="expanded.has(group.parent.id)" @click="toggleExpand(group.parent.id)">
          <component :is="expanded.has(group.parent.id) ? ChevronDown : ChevronRight" :size="20" />
          <span class="group-name"><strong>{{ group.parent.name }}</strong><small v-if="group.parent.disabled" class="status-badge">已停用</small></span>
          <small>{{ group.activeCount }}/{{ group.children.length }}</small>
        </button>
        <span class="row-actions">
          <button v-if="!group.parent.isDefault" class="icon-action" type="button" :aria-label="`编辑${group.parent.name}`" @click="editCategory(group.parent)"><Pencil :size="18" /></button>
          <button class="icon-action" type="button" :aria-label="`${group.parent.disabled ? '启用' : '停用'}${group.parent.name}`" @click="toggleDisabled(group.parent)"><Power :size="18" /></button>
          <button v-if="!group.parent.isDefault" class="icon-action danger" type="button" :aria-label="`删除${group.parent.name}`" @click="requestDelete(group.parent)"><Trash2 :size="18" /></button>
        </span>
      </div>
      <div v-if="expanded.has(group.parent.id)" class="children">
        <div v-for="category in group.children" :key="category.id" class="child-row" :data-category-id="category.id" :data-parent-id="group.parent.id"
          :class="{ disabled: category.disabled, dragging: dragVisual?.id === category.id, 'drop-before': dragVisual?.targetId === category.id && dragVisual.before, 'drop-after': dragVisual?.targetId === category.id && !dragVisual.before }">
          <button class="drag-handle" type="button" :aria-label="`拖动${category.name}调整顺序`" :aria-grabbed="dragVisual?.id === category.id"
            @pointerdown="startDrag(category, $event)" @pointermove="moveDrag" @pointerup="finishDrag" @pointercancel="stopDrag" @contextmenu.prevent
            @keydown.up="moveByKeyboard(category, -1, $event)" @keydown.down="moveByKeyboard(category, 1, $event)"><GripVertical :size="19" /></button>
          <span class="category-icon" :style="iconStyle(category)"><CategoryIcon :name="category.icon" :size="19" /></span>
          <span class="child-name"><span>{{ category.name }}</span><small v-if="category.disabled" class="status-badge">已停用</small></span>
          <span class="row-actions">
            <button v-if="!category.isDefault" class="icon-action" type="button" :aria-label="`编辑${category.name}`" @click="editCategory(category)"><Pencil :size="18" /></button>
            <button class="icon-action" type="button" :aria-label="`${category.disabled ? '启用' : '停用'}${category.name}`" @click="toggleDisabled(category)"><Power :size="18" /></button>
            <button v-if="!category.isDefault" class="icon-action danger" type="button" :aria-label="`删除${category.name}`" @click="requestDelete(category)"><Trash2 :size="18" /></button>
          </span>
        </div>
      </div>
    </section>
  </main>

  <div class="fixed-add">
    <button class="button primary" type="button" @click="requireWrite() && router.push({ name: 'category-new', query: { type } })"><Plus :size="19" />添加分类</button>
  </div>

  <AppDialog :open="Boolean(deleting)" title="确认删除分类" @close="closeDeleteDialog">
    <template v-if="deleteTransactionCount > 0">
      <p>“{{ deleting?.name }}”下有 {{ deleteTransactionCount }} 条流水。为保证账单和统计不丢失，删除前必须把这些流水迁移到其他分类。</p>
      <label>
        <span class="field-label">流水迁移到</span>
        <select v-model="migrationTarget" class="field">
          <option value="" disabled>请选择分类</option>
          <option v-for="category in migrationOptions" :key="category.id" :value="category.id">{{ category.name }}</option>
        </select>
      </label>
      <p v-if="migrationOptions.length === 0" class="field-error">当前没有可用的同类型分类，请先新增分类后再删除。</p>
    </template>
    <p v-else>“{{ deleting?.name }}”下没有流水。确认删除后无法恢复该分类，但不会影响已有账单。</p>
    <template #actions>
      <button class="button secondary" type="button" @click="closeDeleteDialog">取消</button>
      <button class="button danger" type="button" :disabled="busy || (deleteTransactionCount > 0 && !migrationTarget)" @click="confirmDelete">{{ busy ? '处理中' : deleteTransactionCount > 0 ? '迁移并删除' : '确认删除' }}</button>
    </template>
  </AppDialog>
</template>

<style scoped>
.categories-page { padding-bottom: calc(112px + var(--safe-bottom)); }
.type-tabs { margin-bottom: 16px; }
.category-group { margin-bottom: 14px; overflow: hidden; }
.category-group.disabled, .child-row.disabled { background: #fafafa; }
.group-row { display: flex; min-height: 64px; align-items: center; padding: 6px 8px; }
.drag-handle { display: grid; width: 28px; min-width: 28px; height: 44px; place-items: center; border: 0; border-radius: 8px; background: transparent; color: var(--color-text-secondary); cursor: grab; touch-action: none; }
.drag-handle:active { cursor: grabbing; }
.drag-handle:focus-visible { outline: 2px solid var(--color-primary); }
.dragging { opacity: .55; }
.drop-before { box-shadow: inset 0 3px var(--color-primary); }
.drop-after { box-shadow: inset 0 -3px var(--color-primary); }
.expand-button { display: grid; min-width: 0; min-height: 52px; flex: 1; grid-template-columns: 22px minmax(0, 1fr) auto; align-items: center; gap: 7px; padding: 0 4px; border: 0; background: transparent; color: var(--color-text); text-align: left; }
.expand-button > small { color: var(--color-text-secondary); text-align: right; }
.group-name, .child-name { display: flex; min-width: 0; align-items: center; gap: 7px; }
.group-name strong, .child-name > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.status-badge { flex: 0 0 auto; padding: 1px 6px; border-radius: 8px; background: #eceff4; color: var(--color-text-secondary); font-size: 11px; line-height: 20px; }
.row-actions { display: flex; flex: 0 0 auto; align-items: center; gap: 0; }
.icon-action { display: grid; width: 42px; height: 44px; flex: 0 0 42px; place-items: center; border: 0; border-radius: 50%; background: transparent; color: var(--color-text-secondary); }
.icon-action.danger { color: var(--color-danger); }
.children { border-top: 1px solid var(--color-border); }
.child-row { display: flex; min-height: 60px; align-items: center; gap: 9px; padding: 5px 8px 5px 16px; border-bottom: 1px solid var(--color-border); }
.child-row:last-child { border-bottom: 0; }
.category-icon { display: grid; width: 36px; height: 36px; flex: 0 0 36px; place-items: center; border-radius: 11px; }
.child-name { flex: 1; }
.fixed-add { position: fixed; z-index: 8; right: 0; bottom: 0; left: 0; padding: 10px max(16px, calc((100% - 688px) / 2)) calc(10px + var(--safe-bottom)); border-top: 1px solid var(--color-border); background: rgb(255 255 255 / 96%); backdrop-filter: blur(14px); }
.fixed-add .button { width: 100%; }
@media (max-width: 359px) { .icon-action { width: 38px; flex-basis: 38px; } .group-row, .child-row { padding-right: 4px; } }
</style>
